import 'server-only';

export type Post = {
  id: string;
  title: string;
  body: string;
  createdAt: string;
};

const posts: Post[] = [
  {
    id: 'seed-1',
    title: 'Welcome',
    body: 'Write a post to see it appear below.',
    createdAt: new Date().toISOString()
  }
];

export function listPosts(): Post[] {
  return posts.map((post) => ({ ...post }));
}

export function createPost(input: { title: string; body: string }): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title: input.title,
    body: input.body,
    createdAt: new Date().toISOString()
  };

  posts.unshift(post);
  return post;
}

